begin;
select no_plan();
delete from public.push_outbox;
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000006101','push-a@test.invalid'),('00000000-0000-4000-8000-000000006102','push-b@test.invalid');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000006101','QA family','00000000-0000-4000-8000-000000006101');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000006101','00000000-0000-4000-8000-000000006101'),('10000000-0000-4000-8000-000000006101','00000000-0000-4000-8000-000000006102');
insert into auth.sessions(id,user_id) values(gen_random_uuid(),'00000000-0000-4000-8000-000000006101'),(gen_random_uuid(),'00000000-0000-4000-8000-000000006102');
insert into public.push_tokens(id,user_id,family_id,role,platform,token,token_type) values
 ('20000000-0000-4000-8000-000000006101','00000000-0000-4000-8000-000000006101','10000000-0000-4000-8000-000000006101','parent','ios','qa-token-one','apns'),
 ('20000000-0000-4000-8000-000000006102','00000000-0000-4000-8000-000000006102','10000000-0000-4000-8000-000000006101','parent','android','qa-token-two','fcm');
insert into public.push_outbox(family_id,audience,kind,payload) values('10000000-0000-4000-8000-000000006101','parents','exam_finished','{}');
select set_config('test.outbox',(select id::text from public.push_outbox),true);
set local role authenticated;
select throws_ok($$select public.push_claim_v2(1)$$,'42501',null,'parent cannot claim messages');
select throws_ok($$select * from gina.push_deliveries$$,'42501',null,'private receipts not readable');
set local role service_role;
select throws_ok($$select public.push_claim_batch(1)$$,'42501',null,'old unfenced worker fails closed');
select throws_ok($$update public.push_outbox set status='sent'$$,'42501',null,'old direct status updates blocked');
select set_config('test.lease',(select lease_id::text from public.push_claim_v2(1)),true);
select is((select count(*)::int from public.push_claim_v2(1)),0,'active lease cannot be claimed twice');
create function pg_temp.record(n int,st text) returns boolean language sql as $$select public.push_record_delivery(current_setting('test.outbox')::bigint,current_setting('test.lease')::uuid,case when n=1 then '20000000-0000-4000-8000-000000006101'::uuid else '20000000-0000-4000-8000-000000006102'::uuid end,encode(extensions.digest(case when n=1 then 'qa-token-one' else 'qa-token-two' end,'sha256'),'hex'),st,case when st='retry' then 'provider_unavailable' end,case when st='retry' then 3600 end)$$;
create function pg_temp.finish_row() returns text language sql as $$select public.push_finish_delivery(current_setting('test.outbox')::bigint,current_setting('test.lease')::uuid)$$;
select is((select count(*)::int from public.push_delivery_targets(current_setting('test.outbox')::bigint,current_setting('test.lease')::uuid)),2,'both eligible devices initially available');
select throws_ok($$select public.push_delivery_targets(current_setting('test.outbox')::bigint,null)$$,'P0001','push_lease_changed','null lease rejected');
select is(pg_temp.record(1,'sent'),true,'first device accepted');
select is(pg_temp.record(1,'sent'),true,'lost receipt reply is replayable');
select is(pg_temp.record(2,'retry'),true,'second device retry recorded independently');
select is((select count(*)::int from public.push_delivery_targets(current_setting('test.outbox')::bigint,current_setting('test.lease')::uuid)),1,'accepted device excluded from further sends');
select is(pg_temp.finish_row(),'pending','partial transient failure remains retryable');
select is((select count(*)::int from public.push_claim_v2(1)),0,'backoff prevents immediate retry loop');
reset role;
select ok((select next_attempt_at>=now()+interval '1 hour' from public.push_outbox),'provider retry-after is honored');
select is((select attempts from gina.push_deliveries where token_id='20000000-0000-4000-8000-000000006101'),1,'same receipt does not count twice');
update public.push_outbox set next_attempt_at=now()-interval '1 second';
set local role service_role;
select set_config('test.oldlease',current_setting('test.lease'),true);
select set_config('test.lease',(select lease_id::text from public.push_claim_v2(1)),true);
select throws_ok($$select public.push_finish_delivery(current_setting('test.outbox')::bigint,current_setting('test.oldlease')::uuid)$$,'P0001','push_lease_changed','old worker cannot finish a newer claim');
select throws_ok($$select public.push_record_delivery(current_setting('test.outbox')::bigint,current_setting('test.oldlease')::uuid,'20000000-0000-4000-8000-000000006102',repeat('a',64),'sent')$$,'P0001','push_lease_changed','old worker cannot acknowledge a newer claim');
select is(pg_temp.record(2,'sent'),true,'only remaining device is accepted');
select is(pg_temp.finish_row(),'sent','all devices accepted finishes event');
reset role;
select is((select count(*)::int from gina.push_deliveries where status='sent'),2,'both successful receipts retained');
-- Simulate a worker disappearing with no fresh pending event to wake the scheduler.
update public.push_outbox set status='pending',attempts=0,next_attempt_at=now()-interval '1 second';
delete from gina.push_deliveries;
set local role service_role;
select set_config('test.lease',(select lease_id::text from public.push_claim_v2(1)),true);
reset role;
select is(gina.push_delivery_due(),false,'unexpired lease alone does not wake another worker');
update public.push_outbox set claimed_at=now()-interval '6 minutes';
select is(gina.push_delivery_due(),true,'expired sending event wakes scheduler without new pending event');
set local role service_role;
select set_config('test.expiredlease',current_setting('test.lease'),true);
select set_config('test.lease',(select lease_id::text from public.push_claim_v2(1)),true);
select isnt(current_setting('test.lease'),current_setting('test.expiredlease'),'abandoned sending event gets a new lease');
-- A token refresh during a provider request must not delete the replacement token.
reset role;update public.push_tokens set token='qa-token-two-refreshed' where id='20000000-0000-4000-8000-000000006102';set local role service_role;
select is(pg_temp.record(2,'gone'),true,'expired old-token response can be recorded');
reset role;
select is((select token from public.push_tokens where id='20000000-0000-4000-8000-000000006102'),'qa-token-two-refreshed','new token survives stale gone result');
set local role service_role;
select is((select count(*)::int from public.push_delivery_targets(current_setting('test.outbox')::bigint,current_setting('test.lease')::uuid)),2,'replacement token remains eligible');
reset role;update public.push_outbox set attempts=5,claimed_at=now()-interval '6 minutes';set local role service_role;
select is((select count(*)::int from public.push_claim_v2(1)),0,'expired event stops at five claims');
reset role;
select is((select status from public.push_outbox),'failed','retry limit is explicit failure');
select is(gina.push_delivery_due(),false,'exhausted terminal event does not keep waking worker');
select lives_ok($$delete from public.families where id='10000000-0000-4000-8000-000000006101';set constraints all immediate;$$,'family deletion removes delivery metadata');
select is((select count(*)::int from gina.push_deliveries),0,'no orphan device receipts');
select * from finish();rollback;
